(function(){
function css(){if(document.getElementById('fpon-econ-chart-css'))return;const s=document.createElement('style');s.id='fpon-econ-chart-css';s.textContent=`
.econ .metrics{gap:10px!important}.econ .m{position:relative;display:grid!important;grid-template-columns:minmax(105px,.58fr) minmax(220px,1.42fr);gap:12px;align-items:center;padding:13px 14px!important;min-height:142px}.metric-current{min-width:0}.metric-current .mn{margin-bottom:4px}.metric-current .mv{font-size:22px!important;line-height:1.15}.metric-current .mc{margin-top:5px}.metric-week{min-width:0;border-left:1px solid #e7edf3;padding-left:12px}.metric-week-title{font-size:10px;font-weight:900;color:#64778d;margin-bottom:5px}.econ-chart{width:100%;height:70px;display:block;overflow:visible}.econ-chart .grid{stroke:#edf1f5;stroke-width:1}.econ-chart .line{fill:none;stroke:#2f6fb0;stroke-width:2.3;stroke-linecap:round;stroke-linejoin:round}.econ-chart .dot{fill:#fff;stroke:#2f6fb0;stroke-width:1.7}.econ-chart text{font-size:8px;fill:#7d8997}.econ-chart .value{font-size:8.5px;font-weight:900;fill:#315879}.metric-week-table{display:grid;grid-template-columns:repeat(6,minmax(0,1fr));gap:4px;margin-top:6px}.metric-week-cell{padding:5px 3px;border:1px solid #e7edf3;border-radius:7px;background:#fafbfd;text-align:center;min-width:0}.metric-week-date{font-size:8px;color:#7d8997;white-space:nowrap}.metric-week-value{font-size:9px;font-weight:900;color:#314b67;margin-top:2px;white-space:nowrap}.metric-week-note{font-size:9px;color:#8a96a3;margin-top:5px}.metric-no-chart{font-size:10px;line-height:1.5;color:#8a96a3;border-left:1px solid #e7edf3;padding-left:10px}
@media(max-width:700px){.econ .m{grid-template-columns:1fr;padding:12px!important}.metric-week,.metric-no-chart{border-left:0;border-top:1px solid #e7edf3;padding-left:0;padding-top:9px}.metric-current .mv{font-size:20px!important}.econ-chart{height:66px}.metric-week-table{grid-template-columns:repeat(3,1fr)}}
`;document.head.appendChild(s)}
const data={
kospi:{name:'코스피',labels:['8/24','8/25','8/26','8/27','8/28','9/1'],values:[6696.96,6742.74,6808.21,6912.37,6788.88,6767.50]},
kosdaq:{name:'코스닥',labels:['8/24','8/25','8/26','8/27','8/28','9/1'],values:[813.33,827.15,826.87,837.65,838.41,824.37]},
usd:{name:'달러(USD/KRW)',labels:['8/24','8/25','8/26','8/27','8/28','9/1'],values:[1383.19,1382.58,1385.16,1381.76,1377.32,1368.78]},
jpy:{name:'엔화(100JPY)',labels:['8/24','8/25','8/26','8/27','8/28','9/1'],values:[869.36,868.56,869.50,866.88,860.47,856.59]}
};
function fmt(v){return v.toLocaleString('ko-KR',{minimumFractionDigits:2,maximumFractionDigits:2})}
function chart(o){const w=220,h=70,p={l:5,r:7,t:12,b:14},min=Math.min(...o.values),max=Math.max(...o.values),range=(max-min)||1,pts=o.values.map((v,i)=>{const x=p.l+i*(w-p.l-p.r)/(o.values.length-1),y=p.t+(max-v)/range*(h-p.t-p.b);return{x,y,v,label:o.labels[i]}});return `<svg class="econ-chart" viewBox="0 0 ${w} ${h}" preserveAspectRatio="none" aria-label="${o.name} 최근 1주일 추이"><line class="grid" x1="${p.l}" y1="${h-p.b}" x2="${w-p.r}" y2="${h-p.b}"/><polyline class="line" points="${pts.map(q=>q.x+','+q.y).join(' ')}"/>${pts.map(q=>`<circle class="dot" cx="${q.x}" cy="${q.y}" r="2.5"/>`).join('')}</svg>`}
function valueTable(o){return `<div class="metric-week-table">${o.labels.map((d,i)=>`<div class="metric-week-cell"><div class="metric-week-date">${d}</div><div class="metric-week-value">${fmt(o.values[i])}</div></div>`).join('')}</div>`}
function attach(container,seriesMap){if(!container)return;const ms=[...container.querySelectorAll('.m')];ms.forEach(m=>{m.querySelectorAll('.metric-week,.metric-no-chart,.metric-current').forEach(x=>{if(x.classList.contains('metric-current')){while(x.firstChild)m.insertBefore(x.firstChild,x);x.remove()}else x.remove()});const name=(m.querySelector('.mn')?.textContent||'').trim();const current=document.createElement('div');current.className='metric-current';[...m.children].forEach(ch=>current.appendChild(ch));m.appendChild(current);const key=seriesMap.find(x=>name.includes(x.match))?.key;if(key&&data[key]){const week=document.createElement('div');week.className='metric-week';week.innerHTML=`<div class="metric-week-title">최근 1주일 수치 비교</div>${chart(data[key])}${valueTable(data[key])}<div class="metric-week-note">거래일 기준 · 날짜별 실제 표시값</div>`;m.appendChild(week)}else{const no=document.createElement('div');no.className='metric-no-chart';no.textContent='1주일 추이 데이터는 다음 업데이트에서 연결합니다.';m.appendChild(no)}})}
function init(){css();attach(document.querySelector('.ec.stocks'),[{match:'코스피',key:'kospi'},{match:'코스닥',key:'kosdaq'}]);attach(document.querySelector('.ec.fx'),[{match:'달러',key:'usd'},{match:'엔화',key:'jpy'}])}
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>setTimeout(init,1000));else setTimeout(init,1000);
})();